<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageLockAtAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageLockAtAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageLockAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getLockAt returns null on a freshly created holder.
     */
    public function testLockAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithMessageLockAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isLockAtAssigned());
        $this->assertNull($holder->getLockAt());
    }
}
class ImplWithMessageLockAtAttributeHolderUnitTest
{
    use MessageLockAtAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedLockAtRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultLockAt();
    }
}
